/** Routes that exist in CLUSTER_CONTENT, in file order. */
export const CONTENT_ROUTES = CLUSTER_CONTENT.map(c => c.route);
export const LOCALE_ROUTES = LOCALE_CONTENT.map(c => c.route);
export const ALL_CONTENT_ROUTES = [...CONTENT_ROUTES, ...LOCALE_ROUTES];

/**
 * Routes that already have hand-written content in generate-seo.mjs.
 * The cluster generator must skip these, or it would overwrite carefully
 * written pages with generated ones.
 */
export const ALREADY_HANDWRITTEN = [
  'calculators/overtime-pay',
  'calculators/after-tax-income',
  'calculators/car-ownership-cost',
  'calculators/commute-cost',
  'calculators/streaming-cost',
  'calculators/gym-cost-per-visit',
  'calculators/latte-factor',
];

/** Every route the cluster generator is responsible for rendering. */
export const CLUSTER_ROUTES = ALL_CONTENT_ROUTES.filter(r => !ALREADY_HANDWRITTEN.includes(r));

const BY_ROUTE = new Map([...CLUSTER_CONTENT, ...LOCALE_CONTENT].map(c => [c.route, c]));

/** Look up one entry by route. */
export const getContent = route => BY_ROUTE.get(route);

/** English route -> its translated equivalents, for valid reciprocal hreflang. */
export const TRANSLATION_MAP = (() => {
  /** @type {Record<string, {route:string, lang:string}[]>} */
  const m = {};
  for (const c of LOCALE_CONTENT) {
    if (!c.translationOf) continue;
    (m[c.translationOf] ||= []).push({ route: c.route, lang: c.lang });
  }
  return m;
})();

export { H as REPO_URL };
